// ============================================================================
// Config & Safety Gate
// Env-only configuration for the LLM spend circuit breaker.
//   * Safe-ON  flags (SANDBOX_MODE, DRY_RUN, CIRCUIT_BREAKER_ACTIVE_BY_DEFAULT,
//     REQUIRE_ATTRIBUTION, REDACT_PII_BEFORE_LLM) turn OFF only on false/0/no/off.
//   * Safe-OFF flags (LLM_CALLS_ENABLED, ALERTS_ENABLED, LLM_KILL_SWITCH,
//     LEDGER_RESET, FORCE_ALERT) turn ON only on true/1/yes/on.
//   * Typos keep the safe value. Blocked $env => sandbox defaults.
// API keys and webhook URLs never leave this node: only "is set" booleans do.
// Money is handled as integers: prices as micro-USD per million tokens,
// call costs as pico-USD, ledger totals as nano-USD.
// ============================================================================
const TRUTHY = ['true', '1', 'yes', 'on'];
const FALSY = ['false', '0', 'no', 'off'];
let envBlocked = false;
function readEnv(key) {
  try {
    const v = $env[key];
    return v === undefined || v === null ? '' : String(v).trim();
  } catch (e) {
    envBlocked = true;
    return '';
  }
}
const str = (k, d = '') => readEnv(k) || d;
const safeOn = (k) => !FALSY.includes(readEnv(k).toLowerCase());
const safeOff = (k) => TRUTHY.includes(readEnv(k).toLowerCase());
const list = (k, d = '') => (readEnv(k) || d).split(',').map((s) => s.trim()).filter(Boolean);
const configErrors = [];
const warnings = [];
const KEY_RE = /^[A-Za-z0-9_.:-]{1,64}$/;
const intIn = (k, d, min, max) => {
  const raw = readEnv(k);
  if (raw === '') return d;
  const n = Number(raw);
  if (!/^-?\d+$/.test(raw) || n < min || n > max) { configErrors.push(`${k} must be an integer ${min}-${max} (got "${raw}")`); return d; }
  return n;
};
const numIn = (k, d, min, max) => {
  const raw = readEnv(k);
  if (raw === '') return d;
  const n = Number(raw);
  if (!/^\d+(\.\d+)?$/.test(raw) || n < min || n > max) { configErrors.push(`${k} must be a number ${min}-${max} (got "${raw}")`); return d; }
  return n;
};

// ---- Money: decimal USD string -> integer nano-USD (1e-9) ----------------------
// Never uses floating point multiplication on the amount itself.
function usdToNanos(value, label) {
  const s = String(value === undefined || value === null ? '' : value).trim();
  const m = s.match(/^(\d{1,7})(?:\.(\d{1,9}))?$/);
  if (!m) { configErrors.push(`${label} must be a USD amount like 5.00 (got "${s}")`); return null; }
  const nanos = Number(m[1]) * 1e9 + Number(((m[2] || '') + '000000000').slice(0, 9));
  if (!Number.isSafeInteger(nanos) || nanos > 1e6 * 1e9) { configErrors.push(`${label} must be at most 1000000 USD`); return null; }
  return nanos;
}
const usdEnv = (k, d) => { const raw = readEnv(k); const v = usdToNanos(raw === '' ? d : raw, k); return v === null ? usdToNanos(d, k + ' (default)') : v; };
// Price per million tokens (USD, <= 6 decimals) -> integer micro-USD per MTok.
// tokens x microPerMTok = cost in pico-USD, exactly.
function priceToMicro(value, label) {
  const s = String(value === undefined || value === null ? '' : value).trim();
  if (!/^\d{1,4}(\.\d{1,6})?$/.test(s) || Number(s) > 5000) { configErrors.push(`${label} must be a price per million tokens with at most 6 decimals (got "${s}")`); return null; }
  const [i, f = ''] = s.split('.');
  return Number(i) * 1e6 + Number((f + '000000').slice(0, 6));
}
function parseJsonEnv(k, fallback) {
  const raw = readEnv(k);
  if (!raw) return fallback;
  if (raw.length > 100000) { configErrors.push(`${k} is larger than 100 KB`); return fallback; }
  try { return JSON.parse(raw); } catch (e) { configErrors.push(`${k} is not valid JSON: ${e.message}`); return fallback; }
}

// ---- Flags ------------------------------------------------------------------------
const sandboxMode = safeOn('SANDBOX_MODE');
const dryRun = safeOn('DRY_RUN');
const breakerActive = safeOn('CIRCUIT_BREAKER_ACTIVE_BY_DEFAULT');
const llmCallsEnabled = safeOff('LLM_CALLS_ENABLED');
const killSwitch = safeOff('LLM_KILL_SWITCH');
const alertsEnabled = safeOff('ALERTS_ENABLED');
const ledgerReset = safeOff('LEDGER_RESET');
const requireAttribution = safeOn('REQUIRE_ATTRIBUTION');
const redactPii = safeOn('REDACT_PII_BEFORE_LLM');
if (!breakerActive) warnings.push('CIRCUIT_BREAKER_ACTIVE_BY_DEFAULT=false: MONITOR-ONLY mode. Caps and provider breakers are evaluated and alerted but do NOT block LLM calls.');
const currency = str('COST_CURRENCY', 'USD').toUpperCase();
if (currency !== 'USD') configErrors.push(`COST_CURRENCY=${currency} is not supported; provider prices are billed in USD`);

// ---- Clock and budget day -------------------------------------------------------------
const nowMs = (() => {
  const o = str('NOW_OVERRIDE');
  return o && !Number.isNaN(Date.parse(o)) ? Date.parse(o) : Date.now();
})();
const budgetOffsetMin = intIn('BUDGET_UTC_OFFSET_MINUTES', 0, -840, 840);
const localMs = nowMs + budgetOffsetMin * 60000;
const budgetDay = new Date(localMs).toISOString().slice(0, 10);
const dayStartMs = Date.UTC(Number(budgetDay.slice(0, 4)), Number(budgetDay.slice(5, 7)) - 1, Number(budgetDay.slice(8, 10))) - budgetOffsetMin * 60000;
const nextDayStartMs = dayStartMs + 86400000;

// ---- Trigger & webhook auth --------------------------------------------------------
function constantTimeEqual(a, b) {
  const x = String(a || ''), y = String(b || '');
  const len = Math.max(x.length, y.length);
  let diff = x.length ^ y.length;
  for (let i = 0; i < len; i++) diff |= (x.charCodeAt(i) || 0) ^ (y.charCodeAt(i) || 0);
  return diff === 0 && x.length > 0;
}
const raw = $input.first().json || {};
const isWebhook = raw && typeof raw === 'object' && 'body' in raw && 'headers' in raw;
const isSchedule = !isWebhook && raw && typeof raw === 'object' && ('timestamp' in raw || 'Readable date' in raw || 'Day of week' in raw);
const hasWebhookSecret = readEnv('WEBHOOK_SHARED_SECRET').length >= 16;
let webhookBody = null;
if (isWebhook) {
  const headers = Object.fromEntries(Object.entries(raw.headers || {}).map(([k, v]) => [String(k).toLowerCase(), v]));
  const query = raw.query && typeof raw.query === 'object' ? raw.query : {};
  const provided = headers['x-gateway-secret'] !== undefined ? headers['x-gateway-secret'] : query.gateway_secret;
  if (!sandboxMode && !(hasWebhookSecret && constantTimeEqual(provided, readEnv('WEBHOOK_SHARED_SECRET')))) {
    throw new Error('Gateway webhook rejected: WEBHOOK_SHARED_SECRET (16+ chars) must be set and sent as header x-gateway-secret (or ?gateway_secret=).');
  }
  webhookBody = raw.body && typeof raw.body === 'object' ? raw.body : {};
}

// ---- Budgets ---------------------------------------------------------------------------
const softPctDefault = numIn('DAILY_SOFT_CAP_PCT', 80, 1, 100);
const budgetsGlobal = {
  hardNanos: usdEnv('DAILY_HARD_CAP_USD', '5.00'),
  softPct: softPctDefault,
  fromEnv: readEnv('DAILY_HARD_CAP_USD') !== '',
};
const SCOPES = { clients: 'client', workflows: 'workflow', campaigns: 'campaign', costCenters: 'costCenter' };
function parseScopeBudgets(obj, label) {
  const out = { clients: {}, workflows: {}, campaigns: {}, costCenters: {} };
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) { if (obj !== null && obj !== undefined) configErrors.push(`${label} must be a JSON object`); return out; }
  for (const [scope, entries] of Object.entries(obj)) {
    if (!SCOPES[scope]) { configErrors.push(`${label}: unknown scope "${scope}" (use clients, workflows, campaigns, costCenters)`); continue; }
    if (!entries || typeof entries !== 'object' || Array.isArray(entries)) { configErrors.push(`${label}.${scope} must be an object`); continue; }
    for (const [key, b] of Object.entries(entries)) {
      if (!KEY_RE.test(key)) { configErrors.push(`${label}.${scope}: invalid key "${String(key).slice(0, 40)}"`); continue; }
      const hard = usdToNanos(b && b.hardUsd, `${label}.${scope}.${key}.hardUsd`);
      const soft = b && b.softPct !== undefined ? Number(b.softPct) : softPctDefault;
      if (!Number.isFinite(soft) || soft < 1 || soft > 100) { configErrors.push(`${label}.${scope}.${key}.softPct must be 1-100`); continue; }
      if (hard !== null) out[scope][key] = { hardNanos: hard, softPct: soft };
    }
  }
  return out;
}
const scopeBudgets = parseScopeBudgets(parseJsonEnv('BUDGETS_JSON', null), 'BUDGETS_JSON');
const budgets = {
  global: budgetsGlobal,
  scopes: scopeBudgets,
  scopesFromEnv: readEnv('BUDGETS_JSON') !== '',
  perRequestMaxNanos: usdEnv('PER_REQUEST_MAX_USD', '0.25'),
  safetyMarginPct: numIn('BUDGET_SAFETY_MARGIN_PCT', 5, 0, 50),
  softCapAction: (() => { const v = str('SOFT_CAP_ACTION', 'downgrade').toLowerCase(); if (!['downgrade', 'fallback', 'allow'].includes(v)) { configErrors.push('SOFT_CAP_ACTION must be downgrade, fallback or allow'); return 'downgrade'; } return v; })(),
  hardCapTripMode: (() => { const v = str('HARD_CAP_TRIP_MODE', 'trip_scope').toLowerCase(); if (!['trip_scope', 'per_request'].includes(v)) { configErrors.push('HARD_CAP_TRIP_MODE must be trip_scope or per_request'); return 'trip_scope'; } return v; })(),
  criticalBypassesSoftCap: safeOn('CRITICAL_BYPASSES_SOFT_CAP'),
};

// ---- Cost allocation -----------------------------------------------------------------
const sharedCostCenter = str('SHARED_COST_CENTER_KEY', 'shared');
const rawWeights = parseJsonEnv('SHARED_COST_ALLOCATION_JSON', { 'cc-marketing': 60, 'cc-sales': 40 });
const allocationWeights = {};
if (rawWeights && typeof rawWeights === 'object' && !Array.isArray(rawWeights)) {
  for (const [k, w] of Object.entries(rawWeights)) {
    if (!KEY_RE.test(k) || !Number.isInteger(Number(w)) || Number(w) <= 0 || Number(w) > 1000000) configErrors.push(`SHARED_COST_ALLOCATION_JSON entry "${String(k).slice(0, 40)}" needs a positive integer weight`);
    else allocationWeights[k] = Number(w);
  }
} else configErrors.push('SHARED_COST_ALLOCATION_JSON must be an object of cost center -> integer weight');
if (!Object.keys(allocationWeights).length) configErrors.push('SHARED_COST_ALLOCATION_JSON needs at least one cost center');
const rawCcMap = parseJsonEnv('COST_CENTER_MAP_JSON', {});
const costCenterMap = {};
if (rawCcMap && typeof rawCcMap === 'object' && !Array.isArray(rawCcMap)) {
  for (const [k, v] of Object.entries(rawCcMap)) { if (KEY_RE.test(k) && KEY_RE.test(String(v))) costCenterMap[k] = String(v); else configErrors.push(`COST_CENTER_MAP_JSON entry "${String(k).slice(0, 40)}" is invalid`); }
} else configErrors.push('COST_CENTER_MAP_JSON must be an object of client_key -> cost center');

// ---- Pricing (USD per million tokens; verify against provider pricing pages) ----------
// Standard / short-context rates. "long" applies when the prompt exceeds aboveInputTokens.
// OpenAI: cachedInput = cached prompt tokens. Anthropic: cacheWrite = 5-minute cache write,
// cachedInput = cache read. Reasoning tokens are billed as output (included in usage).
const PRICING_AS_OF = '2026-11-17';
const DEFAULT_PRICING = {
  'gpt-6-astra': { provider: 'openai', input: '10', cachedInput: '1', output: '50', long: { aboveInputTokens: 272000, input: '20', cachedInput: '2', output: '75' } },
  'gpt-6.1-sol': { provider: 'openai', input: '2', cachedInput: '0.1', output: '10', long: { aboveInputTokens: 272000, input: '4', cachedInput: '0.2', output: '15' } },
  'gpt-6.1-terra': { provider: 'openai', input: '1', cachedInput: '0.05', output: '5', long: { aboveInputTokens: 272000, input: '2', cachedInput: '0.1', output: '7.5' } },
  'gpt-6-luna': { provider: 'openai', input: '0.1', cachedInput: '0.01', output: '0.5', long: { aboveInputTokens: 272000, input: '0.2', cachedInput: '0.02', output: '0.75' } },
  'gpt-5.5': { provider: 'openai', input: '5', cachedInput: '0.5', output: '30', long: { aboveInputTokens: 272000, input: '10', cachedInput: '1', output: '45' } },
  'gpt-5.4': { provider: 'openai', input: '2.5', cachedInput: '0.25', output: '15', long: { aboveInputTokens: 272000, input: '5', cachedInput: '0.5', output: '22.5' } },
  'gpt-5.4-mini': { provider: 'openai', input: '0.75', cachedInput: '0.075', output: '4.5' },
  'gpt-5.4-nano': { provider: 'openai', input: '0.2', cachedInput: '0.02', output: '1.25' },
  'gpt-5-mini': { provider: 'openai', input: '0.25', cachedInput: '0.025', output: '2' },
  'gpt-5-nano': { provider: 'openai', input: '0.05', cachedInput: '0.005', output: '0.4' },
  'gpt-4.1-mini': { provider: 'openai', input: '0.4', cachedInput: '0.1', output: '1.6' },
  'gpt-4o-mini': { provider: 'openai', input: '0.15', cachedInput: '0.075', output: '0.6' },
  'claude-fable-5-2': { provider: 'anthropic', input: '8', cacheWrite: '10', cachedInput: '0.2', output: '40' },
  'claude-opus-5-5': { provider: 'anthropic', input: '4', cacheWrite: '5', cachedInput: '0.2', output: '20' },
  'claude-sonnet-5-5': { provider: 'anthropic', input: '2', cacheWrite: '2.5', cachedInput: '0.1', output: '10' },
  'claude-haiku-5-5': { provider: 'anthropic', input: '0.1', cacheWrite: '0.125', cachedInput: '0.01', output: '0.5', long: { aboveInputTokens: 100000, input: '0.5', cacheWrite: '0.625', cachedInput: '0.05', output: '2.5' } },
  'claude-sonnet-4-5': { provider: 'anthropic', input: '3', cacheWrite: '3.75', cachedInput: '0.3', output: '15' },
  'claude-haiku-4-5': { provider: 'anthropic', input: '1', cacheWrite: '1.25', cachedInput: '0.1', output: '5' },
};
const pricingOverride = parseJsonEnv('MODEL_PRICING_JSON', null);
const pricingMode = str('MODEL_PRICING_MODE', 'merge').toLowerCase() === 'replace' ? 'replace' : 'merge';
const rawPricing = pricingOverride && typeof pricingOverride === 'object' && !Array.isArray(pricingOverride)
  ? (pricingMode === 'replace' ? pricingOverride : { ...DEFAULT_PRICING, ...pricingOverride })
  : DEFAULT_PRICING;
if (pricingOverride !== null && (typeof pricingOverride !== 'object' || Array.isArray(pricingOverride))) configErrors.push('MODEL_PRICING_JSON must be an object keyed by model id');
const pricing = {};
function rateSet(r, label, provider) {
  const out = { input: priceToMicro(r.input, label + '.input'), cachedInput: priceToMicro(r.cachedInput !== undefined ? r.cachedInput : r.input, label + '.cachedInput'), output: priceToMicro(r.output, label + '.output') };
  out.cacheWrite = provider === 'anthropic' ? priceToMicro(r.cacheWrite !== undefined ? r.cacheWrite : r.input, label + '.cacheWrite') : 0;
  return Object.values(out).some((v) => v === null) ? null : out;
}
for (const [model, r] of Object.entries(rawPricing)) {
  if (!/^[a-z0-9][a-z0-9._-]{1,79}$/i.test(model)) { configErrors.push(`MODEL_PRICING_JSON: invalid model id "${String(model).slice(0, 40)}"`); continue; }
  if (!r || !['openai', 'anthropic'].includes(r.provider)) { configErrors.push(`MODEL_PRICING_JSON.${model}.provider must be openai or anthropic`); continue; }
  const std = rateSet(r, `pricing.${model}`, r.provider);
  if (!std) continue;
  let long = null;
  if (r.long) {
    const above = Number(r.long.aboveInputTokens);
    if (!Number.isInteger(above) || above < 1000) { configErrors.push(`pricing.${model}.long.aboveInputTokens must be an integer >= 1000`); continue; }
    long = rateSet(r.long, `pricing.${model}.long`, r.provider);
    if (!long) continue;
    long.aboveInputTokens = above;
  }
  pricing[model] = { provider: r.provider, ...std, long };
}
const pricingAsOf = str('PRICING_AS_OF', PRICING_AS_OF);
const pricingAgeDays = Number.isNaN(Date.parse(pricingAsOf)) ? null : Math.floor((nowMs - Date.parse(pricingAsOf)) / 86400000);
const maxPricingAge = intIn('PRICING_MAX_AGE_DAYS', 60, 1, 3650);
if (pricingAgeDays === null) configErrors.push('PRICING_AS_OF must be YYYY-MM-DD');
else if (pricingAgeDays > maxPricingAge) warnings.push(`Pricing table is ${pricingAgeDays} days old (PRICING_AS_OF=${pricingAsOf}); verify rates and update MODEL_PRICING_JSON / PRICING_AS_OF.`);
const unpricedPolicy = str('UNPRICED_MODEL_POLICY', 'block').toLowerCase() === 'max_rate' ? 'max_rate' : 'block';
const allowedModels = list('ALLOWED_MODELS').filter((m) => { if (!pricing[m]) { warnings.push(`ALLOWED_MODELS entry ${m} has no price and is ignored`); return false; } return true; });
const DEFAULT_DOWNGRADES = {
  'gpt-6-astra': 'gpt-6-luna', 'gpt-6.1-sol': 'gpt-6-luna', 'gpt-6.1-terra': 'gpt-6-luna', 'gpt-6-sol': 'gpt-6-luna',
  'gpt-5.5': 'gpt-5.4-mini', 'gpt-5.4': 'gpt-5.4-mini', 'gpt-5.4-mini': 'gpt-5.4-nano', 'gpt-5-mini': 'gpt-5-nano',
  'claude-fable-5-2': 'claude-haiku-5-5', 'claude-opus-5-5': 'claude-haiku-5-5', 'claude-sonnet-5-5': 'claude-haiku-5-5',
  'claude-sonnet-4-5': 'claude-haiku-4-5',
