  anthropic: { keySet: readEnv('ANTHROPIC_API_KEY') !== '', endpointValid: anthropicBase.valid, endpointReason: anthropicBase.reason, url: anthropicBase.valid ? anthropicBase.base + '/v1/messages' : null },
};
for (const [p, v] of Object.entries(providers)) if (!v.endpointValid) configErrors.push(v.endpointReason);

const liveCallBlockers = [];
