  return s;
}
const DEFAULT_CLASSIFY = [
  { label: 'cancellation', pattern: '\\b(cancel|cancellation|terminate|churn|close my account)\\b' },
  { label: 'billing', pattern: '\\b(invoice|refund|charge[ds]?|billing|payment|receipt)\\b' },
  { label: 'technical_support', pattern: '\\b(error|bug|crash(es|ed)?|not working|outage|broken|500)\\b' },
  { label: 'sales_inquiry', pattern: '\\b(pricing|quote|demo|trial|upgrade|plan|seats?)\\b' },
];
const DEFAULT_SCORE = {
  base: 40,
  rules: [
    { points: 25, pattern: '\\b(budget (is )?approved|signed off|purchase order)\\b' },
    { points: 20, pattern: '\\b(demo|pricing|quote|proposal)\\b' },
    { points: 15, pattern: '\\b(this quarter|this month|asap|urgent)\\b' },
    { points: 10, pattern: '\\b(enterprise|team of \\d{2,}|\\d{3,} (seats|employees))\\b' },
    { points: -20, pattern: '\\b(student|personal project|just browsing)\\b' },
    { points: -40, pattern: '\\b(unsubscribe|stop emailing|not interested)\\b' },
  ],
  grades: { A: 75, B: 50 },
};
const DEFAULT_TEMPLATES = {
  billing: 'Thanks for reaching out about billing. Our finance team will review your request and reply within one business day.',
  technical_support: 'Thanks for reporting this. A support engineer has been notified and will follow up shortly. Reference: {{request_id}}.',
  sales_inquiry: 'Thanks for your interest. A member of our team will contact you to discuss options for your use case.',
  cancellation: 'We have received your request. A specialist will confirm the next steps with you within one business day.',
  general: 'Thanks for your message. A member of our team will get back to you soon. Reference: {{request_id}}.',
};
const classifyRules = [];
const rawClassify = parseJsonEnv('FALLBACK_CLASSIFY_RULES_JSON', DEFAULT_CLASSIFY);
(Array.isArray(rawClassify) ? rawClassify : []).forEach((r, i) => { const p = safePattern(r && r.pattern, `FALLBACK_CLASSIFY_RULES_JSON[${i}]`); if (p && r.label && KEY_RE.test(r.label)) classifyRules.push({ label: r.label, pattern: p }); });
if (!classifyRules.length) configErrors.push('FALLBACK_CLASSIFY_RULES_JSON must be a non-empty array of {label, pattern}');
const rawScore = parseJsonEnv('FALLBACK_SCORE_RULES_JSON', DEFAULT_SCORE);
