  rawRequests = [];
  source = 'schedule-digest';
} else {
  rawRequests = FIXTURE.requests;
  source = 'synthetic-fixture';
}
if (!Array.isArray(rawRequests)) throw new Error('Request batch must be an array.');
if (rawRequests.length > E.maxRequestsPerRun) throw new Error(`Batch of ${rawRequests.length} requests exceeds MAX_REQUESTS_PER_RUN=${E.maxRequestsPerRun}; nothing was processed.`);

const seen = new Set();
const requests = rawRequests.map((r, index) => {
  const errors = [];
  const flags = [];
  const o = r && typeof r === 'object' && !Array.isArray(r) ? r : {};
  if (o !== r) errors.push('INVALID_REQUEST_OBJECT');
  let requestId = typeof o.request_id === 'string' && KEY_RE.test(o.request_id) ? o.request_id : `req-${String(index + 1).padStart(3, '0')}`;
  if (seen.has(requestId)) { flags.push('DUPLICATE_REQUEST_ID_RENAMED'); requestId = `${requestId}-${index + 1}`; }
  seen.add(requestId);
  const task = String(o.task || '').toLowerCase();
  if (!TASKS.includes(task)) errors.push('UNSUPPORTED_TASK');
  const model = typeof o.model === 'string' && /^[a-z0-9][a-z0-9._-]{1,79}$/i.test(o.model) ? o.model : null;
  if (!model) errors.push('INVALID_MODEL');
  let provider = typeof o.provider === 'string' ? o.provider.toLowerCase() : '';
  if (!provider && model && config.pricing[model]) provider = config.pricing[model].provider;
  if (!['openai', 'anthropic'].includes(provider)) errors.push('INVALID_PROVIDER');
  const input = typeof o.input === 'string' ? o.input : '';
  if (!input.trim()) errors.push('MISSING_INPUT');
  if (input.length > 2000000) errors.push('INPUT_EXCEEDS_HARD_LIMIT');
  const system = typeof o.system === 'string' ? o.system.slice(0, 8000) : '';
  let maxOutput = o.max_output_tokens === undefined ? E.defaultMaxOutput : Number(o.max_output_tokens);
  if (!Number.isInteger(maxOutput) || maxOutput < 1) { errors.push('INVALID_MAX_OUTPUT_TOKENS'); maxOutput = E.defaultMaxOutput; }
  if (maxOutput > E.maxOutputCap) { flags.push('MAX_OUTPUT_CLAMPED'); maxOutput = E.maxOutputCap; }
  const attr = (k) => (typeof o[k] === 'string' && KEY_RE.test(o[k]) ? o[k] : null);
  const client = attr('client_key');
  const workflow = attr('workflow_id');
  if (config.privacy.requireAttribution && (!client || !workflow)) errors.push('MISSING_ATTRIBUTION');
  const clientKey = client || 'unattributed';
  const costCenter = attr('cost_center') || config.allocation.costCenterMap[clientKey] || config.allocation.defaultCostCenter;
  const labels = Array.isArray(o.labels) ? o.labels.filter((l) => typeof l === 'string' && KEY_RE.test(l)).slice(0, 20) : [];
  const vars = {};
  if (o.template_vars && typeof o.template_vars === 'object' && !Array.isArray(o.template_vars)) {
    for (const [k, v] of Object.entries(o.template_vars).slice(0, 20)) if (KEY_RE.test(k) && ['string', 'number'].includes(typeof v)) vars[k] = String(v).slice(0, 200);
  }
  return {
    index,
    requestId,
    task,
    provider,
    model,
    system,
    input,
    inputChars: input.length + system.length,
    inputTooLarge: input.length + system.length > E.maxInputChars,
    maxOutput,
    labels,
    vars,
    priority: o.priority === 'critical' ? 'critical' : 'normal',
    attribution: { client: clientKey, workflow: workflow || 'unattributed', campaign: attr('campaign_id') || 'none', costCenter },
    simulate: config.sandboxMode && o.simulate && typeof o.simulate === 'object' ? o.simulate : null,
    errors,
    flags,
  };
});

return [{ json: {
  source,
  requests,
  fixture: config.sandboxMode ? { ledgerSeed: FIXTURE.ledgerSeed, sandboxBudgets: FIXTURE.sandboxBudgets } : null,
} }];

// ============================================================================
// Load Spend Ledger
// Daily spend ledger (integer nano-USD) from workflow static data, or the
// fixture seed in SANDBOX_MODE (never touches real static data).
//   * Corrupt / unknown ledgers are NOT trusted: every request then uses
//     fallback rules (fail closed) until LEDGER_RESET=true is set deliberately.
//   * Day rollover archives yesterday's totals and clears caps / trips.
//   * Provider breakers past their cooldown move OPEN -> HALF_OPEN (1 probe).
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const intake = $input.first().json;
const SCOPE_KEYS = ['clients', 'workflows', 'campaigns', 'costCenters', 'providers', 'models'];
const clone = (v) => JSON.parse(JSON.stringify(v));

function fresh(day) {
  return {
    version: 1,
    day,
    spentNanos: { global: 0, clients: {}, workflows: {}, campaigns: {}, costCenters: {}, providers: {}, models: {} },
    counts: { requests: 0, llmCalls: 0, downgrades: 0, fallbacks: 0, rejected: 0, providerFailures: 0 },
    tokens: { input: 0, cachedInput: 0, cacheWrite: 0, output: 0 },
    trips: {},
    breakers: { openai: { state: 'CLOSED', consecutiveFailures: 0, openedAt: null, reopenAt: null, reason: null }, anthropic: { state: 'CLOSED', consecutiveFailures: 0, openedAt: null, reopenAt: null, reason: null } },
    alertsSent: {},
    history: [],
    updatedAt: null,
  };
}
const nonNegInt = (v) => Number.isSafeInteger(v) && v >= 0;
function validate(l) {
  const e = [];
  if (!l || typeof l !== 'object' || Array.isArray(l)) return ['ledger is not an object'];
  if (l.version !== 1) e.push(`unsupported ledger version ${JSON.stringify(l.version)}`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(l.day))) e.push('ledger.day is not YYYY-MM-DD');
  const s = l.spentNanos || {};
  if (!nonNegInt(s.global)) e.push('spentNanos.global is not a non-negative integer');
  for (const k of SCOPE_KEYS) {
    if (!s[k] || typeof s[k] !== 'object' || Array.isArray(s[k])) { e.push(`spentNanos.${k} missing`); continue; }
    for (const [key, v] of Object.entries(s[k])) if (!nonNegInt(v)) { e.push(`spentNanos.${k}.${key} is not a non-negative integer`); break; }
  }
  for (const k of ['clients', 'workflows', 'campaigns']) {
    const sum = Object.values(s[k] || {}).reduce((a, b) => a + (nonNegInt(b) ? b : 0), 0);
    if (nonNegInt(s.global) && sum > s.global) e.push(`spentNanos.${k} adds up to more than the global total`);
  }
  for (const p of ['openai', 'anthropic']) {
    const b = l.breakers && l.breakers[p];
    if (!b || !['CLOSED', 'OPEN', 'HALF_OPEN'].includes(b.state) || !nonNegInt(b.consecutiveFailures)) e.push(`breakers.${p} is invalid`);
  }
  for (const k of ['counts', 'tokens']) if (!l[k] || Object.values(l[k]).some((v) => !nonNegInt(v))) e.push(`${k} contains invalid values`);
  if (!l.trips || typeof l.trips !== 'object' || !l.alertsSent || typeof l.alertsSent !== 'object' || !Array.isArray(l.history)) e.push('trips / alertsSent / history missing');
  return e;
}

const events = [];
let ledger;
let ledgerSource;
if (config.sandboxMode) {
  ledger = intake.fixture && intake.fixture.ledgerSeed ? clone(intake.fixture.ledgerSeed) : fresh(config.budgetDay);
  ledger.day = config.budgetDay; // the seed always represents "today" so scenarios are date-independent
  ledgerSource = 'fixture-seed';
} else {
  const sd = $getWorkflowStaticData('global');
  ledger = sd.llmLedger === undefined ? fresh(config.budgetDay) : clone(sd.llmLedger);
  ledgerSource = sd.llmLedger === undefined ? 'new' : 'static-data';
}
let ledgerErrors = validate(ledger);
let ledgerTrusted = ledgerErrors.length === 0;
if (ledgerTrusted && ledger.day > config.budgetDay) { ledgerErrors = [`ledger day ${ledger.day} is after the current budget day ${config.budgetDay} (clock moved backwards?)`]; ledgerTrusted = false; }
if (!ledgerTrusted) {
  if (config.ledger.reset) {
    events.push({ type: 'LEDGER_RESET', scope: 'global', key: 'ledger', detail: `Ledger reset by LEDGER_RESET=true: ${ledgerErrors.slice(0, 3).join('; ')}` });
    ledger = fresh(config.budgetDay);
    ledgerTrusted = true;
    ledgerSource = 'reset';
  } else {
    events.push({ type: 'LEDGER_UNTRUSTED', scope: 'global', key: 'ledger', detail: `Spend ledger failed validation; all requests use fallback rules until it is fixed or LEDGER_RESET=true. ${ledgerErrors.slice(0, 3).join('; ')}` });
  }
}

let rolledOver = null;
if (ledgerTrusted && ledger.day !== config.budgetDay) {
  rolledOver = { from: ledger.day, to: config.budgetDay };
  const archived = { day: ledger.day, spentNanos: ledger.spentNanos.global, requests: ledger.counts.requests, llmCalls: ledger.counts.llmCalls, fallbacks: ledger.counts.fallbacks };
  const next = fresh(config.budgetDay);
  next.breakers = ledger.breakers;
  next.history = [archived, ...ledger.history].slice(0, config.ledger.historyDays);
  ledger = next;
}
if (ledgerTrusted) {
  for (const [p, b] of Object.entries(ledger.breakers)) {
    if (b.state === 'OPEN' && b.reopenAt && Date.parse(b.reopenAt) <= config.nowMs) {
      ledger.breakers[p] = { ...b, state: 'HALF_OPEN' };
      events.push({ type: 'BREAKER_HALF_OPEN', scope: 'provider', key: p, detail: `${p} cooldown elapsed; one probe request is allowed.` });
    }
  }
}

// Effective budgets: env values win. In SANDBOX_MODE only, the fixture's example
// budgets fill in for budget variables that are not set, so every scenario runs.
const fx = config.sandboxMode && intake.fixture ? intake.fixture.sandboxBudgets : null;
const effectiveBudgets = clone(config.budgets);
if (fx) {
  if (!config.budgets.global.fromEnv && fx.global) {
    const m = String(fx.global.hardUsd).match(/^(\d{1,7})(?:\.(\d{1,9}))?$/);
    if (m) effectiveBudgets.global = { hardNanos: Number(m[1]) * 1e9 + Number(((m[2] || '') + '000000000').slice(0, 9)), softPct: Number(fx.global.softPct) || config.budgets.global.softPct, fromEnv: false, fromFixture: true };
  }
  if (!config.budgets.scopesFromEnv && fx.scopes) {
    for (const [scope, entries] of Object.entries(fx.scopes)) {
      effectiveBudgets.scopes[scope] = effectiveBudgets.scopes[scope] || {};
      for (const [k, b] of Object.entries(entries)) {
        const m = String(b.hardUsd).match(/^(\d{1,7})(?:\.(\d{1,9}))?$/);
        if (m) effectiveBudgets.scopes[scope][k] = { hardNanos: Number(m[1]) * 1e9 + Number(((m[2] || '') + '000000000').slice(0, 9)), softPct: Number(b.softPct) || config.budgets.global.softPct };
      }
    }
    effectiveBudgets.scopesFromFixture = true;
  }
}

return [{ json: { source: intake.source, requests: intake.requests, ledger, ledgerTrusted, ledgerSource, ledgerErrors, rolledOver, effectiveBudgets, events } }];

// ============================================================================
// Circuit Breaker & Router
// Pre-flight decision for every request, in batch order:
//   1. fail-closed gates: invalid request, config errors, untrusted ledger,
//      kill switch, oversized input, unpriced / disallowed model
//   2. provider breaker (OPEN -> fallback, HALF_OPEN -> one probe)
//   3. per-request cost ceiling (downgrade if that fits, else fallback)
//   4. hard caps (global, client, workflow, campaign, cost center): a projected
//      overrun falls back and, in trip_scope mode, trips that scope for the day
//   5. soft caps: downgrade model + clamp output (or fallback / allow)
// Costs are WORST-CASE estimates (conservative chars-per-token, full max output)
// and are reserved in-batch so one batch cannot overshoot a cap.
// Monitor-only mode (CIRCUIT_BREAKER_ACTIVE_BY_DEFAULT=false) records steps 2-5
// as "would block" but lets the call proceed; step 1 always applies.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const L = $input.first().json;
const ledger = L.ledger;
const B = L.effectiveBudgets;
const E = config.estimation;
const enforce = config.breaker.active;
const margin = B.safetyMarginPct;

// ---- pricing ---------------------------------------------------------------------
function resolvePrice(model) {
  if (config.pricing[model]) return { key: model, ...config.pricing[model] };
  // dated snapshots: gpt-5.4-2026-03-05, claude-haiku-4-5-20251001
  const hit = Object.keys(config.pricing).filter((k) => model.startsWith(k + '-') && /^(\d{8}|\d{4}-\d{2}-\d{2})$/.test(model.slice(k.length + 1))).sort((a, b) => b.length - a.length)[0];
  if (hit) return { key: hit, snapshot: true, ...config.pricing[hit] };
  return null;
}
function maxRate(provider) {
  const ps = Object.values(config.pricing).filter((p) => p.provider === provider);
  if (!ps.length) return null;
  const top = (k) => Math.max(...ps.map((p) => Math.max(p[k], p.long ? p.long[k] : 0)));
  return { key: `max-rate:${provider}`, provider, input: top('input'), cachedInput: top('input'), cacheWrite: top('cacheWrite'), output: top('output'), long: null, maxRate: true };
}
const inputTokensEst = (chars) => Math.ceil(chars / E.charsPerToken) + E.overheadTokens;
function estimateNanos(price, inTok, outTok) {
  const r = price.long && inTok > price.long.aboveInputTokens ? price.long : price;
  const pico = inTok * r.input + outTok * r.output;
  return Math.ceil(pico / 1000);
}

// ---- allocation (largest remainder, exact integer split) ---------------------------
function allocate(nanos, weights) {
  const keys = Object.keys(weights).sort();
  const total = keys.reduce((s, k) => s + weights[k], 0);
  const parts = keys.map((k) => { const exact = (nanos * weights[k]) / total; return { k, base: Math.floor(exact), rem: exact - Math.floor(exact) }; });
  let left = nanos - parts.reduce((s, p) => s + p.base, 0);
  parts.slice().sort((a, b) => b.rem - a.rem || (a.k < b.k ? -1 : 1)).forEach((p) => { if (left > 0) { p.base++; left--; } });
  return Object.fromEntries(parts.map((p) => [p.k, p.base]));
}

// ---- scope bookkeeping ---------------------------------------------------------------
const PLURAL = { client: 'clients', workflow: 'workflows', campaign: 'campaigns', costCenter: 'costCenters' };
const reserved = {}; // scopeKey -> nanos reserved by earlier allowed requests in this batch
const tripsThisRun = {};
const events = [...L.events];
const eventSeen = new Set(events.map((e) => `${e.type}:${e.scope}:${e.key}`));
const pushEvent = (type, scope, key, detail) => { const id = `${type}:${scope}:${key}`; if (!eventSeen.has(id)) { eventSeen.add(id); events.push({ type, scope, key, detail }); } };
const spentOf = (scope, key) => (scope === 'global' ? ledger.spentNanos.global : (ledger.spentNanos[PLURAL[scope]] || {})[key] || 0);
const budgetOf = (scope, key) => (scope === 'global' ? B.global : (B.scopes[PLURAL[scope]] || {})[key] || null);
const effHard = (b) => Math.floor((b.hardNanos * (100 - margin)) / 100);
const softLine = (b) => Math.floor((b.hardNanos * b.softPct) / 100);
const usd = (n) => '$' + (n / 1e9).toFixed(4);
function scopesFor(a, nanos) {
  const out = [
    { scope: 'global', key: 'global', share: nanos },
    { scope: 'client', key: a.client, share: nanos },
    { scope: 'workflow', key: a.workflow, share: nanos },
    { scope: 'campaign', key: a.campaign, share: nanos },
  ];
  if (a.costCenter === config.allocation.sharedKey) {
    const split = allocate(nanos, config.allocation.weights);
    for (const [k, v] of Object.entries(split)) out.push({ scope: 'costCenter', key: k, share: v });
  } else out.push({ scope: 'costCenter', key: a.costCenter, share: nanos });
  return out.map((s) => ({ ...s, id: s.scope === 'global' ? 'global' : `${s.scope}:${s.key}` }));
}

const probesUsed = {};
const decisions = L.requests.map((req) => {
  const d = {
    index: req.index, requestId: req.requestId, task: req.task, provider: req.provider,
    requestedModel: req.model, model: req.model, maxOutput: req.maxOutput, priority: req.priority,
    attribution: req.attribution, labels: req.labels, vars: req.vars, system: req.system, input: req.input,
    inputChars: req.inputChars, simulate: req.simulate,
    route: 'llm', reason: null, downgradedFrom: null, estimateNanos: 0, estInputTokens: 0, priceKey: null,
    callMode: null, wouldRoute: null, flags: [...req.flags], softCapHits: [], monitorWouldBlock: [],
  };
  const fallback = (reason) => { d.route = 'fallback'; d.reason = reason; return d; };
  if (req.errors.length) { d.route = 'rejected'; d.reason = req.errors[0]; d.flags.push(...req.errors.slice(1)); return d; }
  if (config.configErrors.length) return fallback('CONFIG_ERROR');
  if (!L.ledgerTrusted) return fallback('LEDGER_UNTRUSTED');
  if (config.breaker.killSwitch) return fallback('KILL_SWITCH');
  if (req.inputTooLarge) return fallback('INPUT_TOO_LARGE');
  let price = resolvePrice(req.model);
  if (!price && config.unpricedPolicy === 'max_rate') { price = maxRate(req.provider); if (price) d.flags.push('UNPRICED_MODEL_CHARGED_MAX_RATE'); }
  if (!price) return fallback('UNPRICED_MODEL');
  if (price.provider !== req.provider) { d.route = 'rejected'; d.reason = 'PROVIDER_MODEL_MISMATCH'; return d; }
  if (config.allowedModels.length && !config.allowedModels.includes(price.key)) return fallback('MODEL_NOT_ALLOWED');
  if (price.snapshot) d.flags.push('PRICED_AS_' + price.key);
  d.priceKey = price.key;
  d.estInputTokens = inputTokensEst(req.inputChars);
  d.estimateNanos = estimateNanos(price, d.estInputTokens, d.maxOutput);

  // Enforcement checks: block() records a reason; in monitor-only mode it only flags.
  let blocked = null;
  const block = (reason) => { if (enforce) { blocked = blocked || reason; } else { d.monitorWouldBlock.push(reason); pushEvent('MONITOR_ONLY_WOULD_BLOCK', 'request', reason, `Monitor-only mode let a call through that would have been blocked (${reason}).`); } };

  // 2. provider breaker
  const br = ledger.breakers[req.provider] || { state: 'CLOSED' };
  if (br.state === 'OPEN') block('BREAKER_OPEN');
  else if (br.state === 'HALF_OPEN') { if (probesUsed[req.provider]) block('BREAKER_HALF_OPEN'); else d.flags.push('BREAKER_PROBE'); }
  if (blocked) return fallback(blocked);

  const downgradeTo = (target, why) => {
    const p2 = resolvePrice(target);
    d.downgradedFrom = d.model; d.model = target; d.priceKey = p2.key;
    d.estimateNanos = estimateNanos(p2, d.estInputTokens, d.maxOutput);
    d.flags.push(why);
  };
  // 3. per-request ceiling
  if (d.estimateNanos > B.perRequestMaxNanos) {
    const t = config.downgrades[price.key];
    if (t && enforce) {
      downgradeTo(t, 'REQUEST_CEILING_DOWNGRADE');
      if (d.estimateNanos > B.perRequestMaxNanos) { d.maxOutput = Math.min(d.maxOutput, E.softCapMaxOutput); d.estimateNanos = estimateNanos(resolvePrice(t), d.estInputTokens, d.maxOutput); }
      if (d.estimateNanos > B.perRequestMaxNanos) block('REQUEST_COST_CEILING');
    } else block('REQUEST_COST_CEILING');
  }
  if (blocked) return fallback(blocked);

  // 4. tripped scopes and hard caps
  let scopes = scopesFor(d.attribution, d.estimateNanos);
  const trippedHit = scopes.find((s) => ledger.trips[s.id] || tripsThisRun[s.id]);
  if (trippedHit) {
    if (ledger.trips[trippedHit.id]) pushEvent('HARD_CAP_TRIPPED', trippedHit.scope, trippedHit.key, `${trippedHit.id} is tripped for budget day ${ledger.day}; requests in this scope use fallback rules until the next budget day.`);
    block('HARD_CAP_TRIPPED');
  }
  if (!blocked) {
    for (const s of scopes) {
      const b = budgetOf(s.scope, s.key);
      if (!b) continue;
      const projected = spentOf(s.scope, s.key) + (reserved[s.id] || 0) + s.share;
      if (projected > effHard(b)) {
        const reason = 'HARD_CAP_' + s.scope.replace(/[A-Z]/g, (c) => '_' + c).toUpperCase();
        if (enforce && B.hardCapTripMode === 'trip_scope') {
          tripsThisRun[s.id] = { at: config.now, reason, requestId: d.requestId };
          pushEvent('HARD_CAP_TRIPPED', s.scope, s.key, `${s.id} tripped: projected ${usd(projected)} > hard cap ${usd(b.hardNanos)} (minus ${margin}% safety margin). LLM calls for this scope use fallback rules until the next budget day.`);
        } else pushEvent('HARD_CAP_BLOCKED', s.scope, s.key, `${s.id}: a request projected to ${usd(projected)} exceeded the hard cap ${usd(b.hardNanos)} and used fallback rules.`);
        block(reason);
        break;
      }
    }
  }
  if (blocked) return fallback(blocked);

  // 5. soft caps
  for (const s of scopes) {
    const b = budgetOf(s.scope, s.key);
    if (!b) continue;
    const projected = spentOf(s.scope, s.key) + (reserved[s.id] || 0) + s.share;
    if (projected > softLine(b)) {
      d.softCapHits.push(s.id);
      pushEvent('SOFT_CAP_REACHED', s.scope, s.key, `${s.id} passed ${b.softPct}% of its ${usd(b.hardNanos)} daily cap (projected ${usd(projected)}).`);
    }
  }
  if (d.softCapHits.length) {
    if (req.priority === 'critical' && B.criticalBypassesSoftCap) d.flags.push('SOFT_CAP_BYPASSED_CRITICAL');
    else if (B.softCapAction === 'allow') d.flags.push('SOFT_CAP_ALLOWED');
    else if (B.softCapAction === 'fallback') block('SOFT_CAP_' + d.softCapHits[0].split(':')[0].replace(/[A-Z]/g, (c) => '_' + c).toUpperCase());
    else if (enforce) {
      d.maxOutput = Math.min(d.maxOutput, E.softCapMaxOutput);
      const t = config.downgrades[d.priceKey];
      if (t) downgradeTo(t, 'SOFT_CAP_DOWNGRADE');
      else { d.estimateNanos = estimateNanos(resolvePrice(d.priceKey), d.estInputTokens, d.maxOutput); d.flags.push('SOFT_CAP_OUTPUT_CLAMPED_NO_DOWNGRADE'); }
    } else d.monitorWouldBlock.push('SOFT_CAP_DOWNGRADE');
  }
  if (blocked) return fallback(blocked);

  // Call mode
  if (config.sandboxMode) d.callMode = 'simulate';
  else if (!config.llm.liveCallsAllowed) { d.wouldRoute = 'llm'; return fallback(config.dryRun ? 'DRY_RUN' : config.llm.callsEnabled ? 'LLM_CALLS_BLOCKED' : 'LLM_CALLS_DISABLED'); }
  else if (!config.llm.providers[req.provider].keySet) { d.wouldRoute = 'llm'; return fallback('PROVIDER_KEY_MISSING'); }
  else d.callMode = 'live';

  if (br.state === 'HALF_OPEN') probesUsed[req.provider] = true;
  scopes = scopesFor(d.attribution, d.estimateNanos);
  for (const s of scopes) reserved[s.id] = (reserved[s.id] || 0) + s.share;
  return d;
});

return [{ json: {
  source: L.source,
  decisions,
  ledger,
  ledgerTrusted: L.ledgerTrusted,
  ledgerSource: L.ledgerSource,
  ledgerErrors: L.ledgerErrors,
  rolledOver: L.rolledOver,
  effectiveBudgets: B,
  reservedNanos: reserved,
  tripsThisRun,
  events,
  monitorOnly: !enforce,
  llmCallCount: decisions.filter((d) => d.route === 'llm').length,
} }];

// ============================================================================
// Expand LLM Calls
// One item per request routed to a provider. Builds the provider body
// (OpenAI Chat Completions or Anthropic Messages). API keys are NOT added
// here: the HTTP node reads them from $env in its headers. Optional PII
// redaction (emails, phone numbers, card-like numbers) runs before sending.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const batch = $input.first().json;

const TASK_PROMPTS = {
  classify: (d) => `Classify the user's message into exactly one label from this list: ${(d.labels.length ? d.labels : config.fallback.classifyRules.map((r) => r.label).concat('general')).join(', ')}. Reply with the label only.`,
  score: () => 'Score this sales lead from 0 to 100 for purchase intent. Reply with the integer score only.',
  reply: () => 'Write a short, polite first reply (max 80 words) to this customer message. Do not invent facts, prices or commitments.',
