const results = [];
const aligned = calls.length === responses.length;
for (let i = 0; i < calls.length; i++) {
  const c = calls[i];
  const d = batch.decisions.find((x) => x.index === c.index);
  const rec = { index: c.index, requestId: c.requestId, provider: c.provider, model: c.model, mode: c.mode, redactions: c.redactions, ok: false, errorCode: null, message: null, retryAfterSec: null, countsAsFailure: false, usage: null, costPico: 0, costNanos: 0, charged: 'none', text: '', flags: [] };
