// ============================================================================
// Fallback Rules & Cost Allocation
// Builds one result per request:
//   * LLM success      -> provider output (normalised for classify / score)
//   * fallback / failed -> deterministic rules: regex classification,
//                         rule-based lead scoring, template replies, regex
//                         extraction, extractive summaries (no network, ~0 ms)
//   * rejected         -> error, no output
// Then attributes every cost to client, workflow, campaign and cost center.
// "Shared" cost-center spend is split by SHARED_COST_ALLOCATION_JSON weights
// with an exact largest-remainder split (parts always sum to the total).
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const batch = $input.first().json;
const calls = batch.calls || [];
