if (allocErrors.length) throw new Error('Cost allocation arithmetic check failed for ' + allocErrors.join(', ') + '; ledger not updated.');
const ccTotal = Object.values(deltas.costCenters).reduce((a, b) => a + b, 0);
if (ccTotal !== deltas.global) throw new Error(`Cost-center allocation (${ccTotal}) does not equal run spend (${deltas.global}); ledger not updated.`);

return [{ json: { ...batch, results, deltas, tokens, counts } }];

// ============================================================================
// Commit Spend Ledger
// Applies this run's actual (or conservatively estimated) costs, scope trips
// and provider breaker transitions to the daily ledger.
//   * Breaker: consecutive provider failures >= BREAKER_FAILURE_THRESHOLD
//     -> OPEN for BREAKER_COOLDOWN_MINUTES; provider budget / quota exhausted
//     -> OPEN until the next budget day; a HALF_OPEN probe that fails re-opens
//     immediately, one that succeeds closes the breaker.
//   * Persisted to workflow static data only in live, non-dry-run executions
//     with a trusted ledger. SANDBOX_MODE never writes static data.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const batch = $input.first().json;
const clone = (v) => JSON.parse(JSON.stringify(v));
const ledger = clone(batch.ledger);
const events = [...batch.events];
const MAX_KEYS = 5000;
const usd = (n) => '$' + (n / 1e9).toFixed(4);

function addInto(map, key, v) {
  if (!v) return;
  let k = key;
  if (map[k] === undefined && Object.keys(map).length >= MAX_KEYS) k = '__other__';
  const next = (map[k] || 0) + v;
  if (!Number.isSafeInteger(next)) throw new Error(`Ledger arithmetic overflow on ${key}; ledger not updated.`);
  map[k] = next;
}
if (batch.ledgerTrusted) {
  const D = batch.deltas;
  const g = ledger.spentNanos.global + D.global;
  if (!Number.isSafeInteger(g) || g < 0) throw new Error('Ledger arithmetic overflow on global spend; ledger not updated.');
  ledger.spentNanos.global = g;
  for (const k of ['clients', 'workflows', 'campaigns', 'costCenters', 'providers', 'models']) for (const [key, v] of Object.entries(D[k])) addInto(ledger.spentNanos[k], key, v);
  for (const k of Object.keys(batch.tokens)) ledger.tokens[k] += batch.tokens[k];
  for (const k of Object.keys(batch.counts)) ledger.counts[k] += batch.counts[k];
  for (const [id, t] of Object.entries(batch.tripsThisRun)) ledger.trips[id] = t;

  // provider breakers, in call order
  for (const c of batch.calls || []) {
    if (c.errorCode === 'RESPONSE_ALIGNMENT_ERROR') continue;
    const b = ledger.breakers[c.provider];
    if (c.ok) {
      // Exhausted credit / quota is account-level: a later success in the same
      // batch does not close it (only the next budget day's probe does).
      if (b.state === 'OPEN' && b.reason === 'PROVIDER_BUDGET_EXCEEDED') { b.consecutiveFailures = 0; continue; }
      if (b.state === 'HALF_OPEN') events.push({ type: 'BREAKER_CLOSED', scope: 'provider', key: c.provider, detail: `${c.provider} probe succeeded; breaker closed.` });
      ledger.breakers[c.provider] = { state: 'CLOSED', consecutiveFailures: 0, openedAt: null, reopenAt: null, reason: null };
      continue;
    }
    if (!c.countsAsFailure) continue;
    b.consecutiveFailures += 1;
    const budgetHit = c.errorCode === 'PROVIDER_BUDGET_EXCEEDED';
    const shouldOpen = budgetHit || b.state === 'HALF_OPEN' || b.consecutiveFailures >= config.breaker.failureThreshold;
    if (shouldOpen && b.state !== 'OPEN') {
      const reopenAt = budgetHit ? new Date(config.nextDayStartMs).toISOString() : new Date(config.nowMs + config.breaker.cooldownMin * 60000).toISOString();
      Object.assign(b, { state: 'OPEN', openedAt: config.now, reopenAt, reason: c.errorCode });
      if (budgetHit) events.push({ type: 'PROVIDER_BUDGET_EXCEEDED', scope: 'provider', key: c.provider, detail: `${c.provider} reported exhausted credit / quota. Breaker open until ${reopenAt}; requests use fallback rules.` });
      events.push({ type: 'BREAKER_OPENED', scope: 'provider', key: c.provider, detail: `${c.provider} breaker opened after ${b.consecutiveFailures} consecutive failure(s) (last: ${c.errorCode}); reopens for a probe at ${reopenAt}.` });
    }
  }
  ledger.updatedAt = config.now;
}

// Utilisation summary (for the response, alert and report)
const B = batch.effectiveBudgets;
const PLURAL = { client: 'clients', workflow: 'workflows', campaign: 'campaigns', costCenter: 'costCenters' };
const pct = (a, b) => (b > 0 ? ((a / b) * 100).toFixed(1) : null);
const scopeRows = [];
for (const [scope, plural] of Object.entries(PLURAL)) {
  const spent = ledger.spentNanos[plural] || {};
  const keys = new Set([...Object.keys(spent), ...Object.keys(B.scopes[plural] || {})]);
  for (const key of keys) {
    const b = (B.scopes[plural] || {})[key];
    const s = spent[key] || 0;
    scopeRows.push({ scope, key, spentNanos: s, hardNanos: b ? b.hardNanos : null, pctOfCap: b ? pct(s, b.hardNanos) : null, tripped: !!ledger.trips[`${scope}:${key}`] });
  }
}
scopeRows.sort((a, b) => b.spentNanos - a.spentNanos || (a.scope + a.key < b.scope + b.key ? -1 : 1));
const utilization = {
  budgetDay: ledger.day,
  globalSpentNanos: ledger.spentNanos.global,
  globalHardNanos: B.global.hardNanos,
  globalSoftNanos: Math.floor((B.global.hardNanos * B.global.softPct) / 100),
  globalPct: pct(ledger.spentNanos.global, B.global.hardNanos),
  globalTripped: !!ledger.trips.global,
  runSpendNanos: batch.deltas.global,
  scopes: scopeRows,
  providers: ledger.spentNanos.providers,
  models: ledger.spentNanos.models,
  costCenters: ledger.spentNanos.costCenters,
  breakers: Object.fromEntries(Object.entries(ledger.breakers).map(([p, b]) => [p, { state: b.state, consecutiveFailures: b.consecutiveFailures, reopenAt: b.reopenAt, reason: b.reason }])),
  trips: Object.keys(ledger.trips),
};

let persisted = false;
let persistNote;
if (!config.ledger.persist) persistNote = config.sandboxMode ? 'SANDBOX_MODE: static data untouched' : 'DRY_RUN: static data untouched';
else if (!batch.ledgerTrusted) persistNote = 'Ledger untrusted: left unchanged for inspection (set LEDGER_RESET=true to start fresh)';
else {
  const sd = $getWorkflowStaticData('global');
  sd.llmLedger = ledger;
  persisted = true;
  persistNote = 'Saved to workflow static data (persists for active, production executions)';
}

return [{ json: { ...batch, ledgerAfter: ledger, utilization, events, persisted, persistNote } }];

// ============================================================================
// Gateway Response
// The JSON returned to webhook callers (and kept in the run data). Contains
// outputs, routing, usage, cost and attribution, never prompts, API keys or
// webhook URLs. Costs are reported as exact decimal USD strings.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const b = $input.first().json;
const usd = (nanos) => { const s = String(Math.max(0, nanos)).padStart(10, '0'); return s.slice(0, -9) + '.' + s.slice(-9); };
const response = {
  run_id: config.runId,
  mode: config.sandboxMode ? 'sandbox' : config.dryRun ? 'dry_run' : 'live',
  breaker_mode: b.monitorOnly ? 'monitor_only' : 'enforcing',
  budget_day: b.utilization.budgetDay,
  results: b.results.map((r) => ({
    request_id: r.request_id,
    task: r.task,
    status: r.status,
    provider: r.provider,
    requested_model: r.requested_model,
    model_used: r.model_used,
    downgraded_from: r.downgraded_from,
    output: r.output,
    fallback: r.fallback,
    usage: r.usage,
    cost_usd: usd(r.cost_nanos),
    estimate_usd: usd(r.estimate_nanos),
    charged: r.charged,
    attribution: r.attribution,
    allocation_usd: Object.fromEntries(Object.entries(r.allocation).map(([k, v]) => [k, usd(v)])),
    flags: r.flags,
    ...(r.monitor_would_block && r.monitor_would_block.length ? { monitor_would_block: r.monitor_would_block } : {}),
    ...(r.would_route ? { would_route: r.would_route } : {}),
  })),
  spend: {
    run_usd: usd(b.utilization.runSpendNanos),
    day_total_usd: usd(b.utilization.globalSpentNanos),
    day_hard_cap_usd: usd(b.utilization.globalHardNanos),
    day_pct_of_cap: b.utilization.globalPct,
    global_tripped: b.utilization.globalTripped,
  },
  breakers: b.utilization.breakers,
  events: b.events.map((e) => ({ type: e.type, scope: e.scope, key: e.key })),
};
return [{ json: { ...b, response } }];

// ============================================================================
// Cost Alert Builder
// Slack Block Kit + Teams Adaptive Card cost alert. Fires on new events
// (soft cap, hard-cap trip, breaker opened, provider budget exhausted, ledger
// untrusted, monitor-only would-block) and on the daily digest schedule.
// Each event alerts once per budget day (FORCE_ALERT=true overrides).
// CRM-free: content is attribution keys, models, amounts and reasons only.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const b = $('Gateway Response').first().json;
const A = config.alerts;
const U = b.utilization;
const ALERT_TYPES = ['LEDGER_UNTRUSTED', 'LEDGER_RESET', 'PROVIDER_BUDGET_EXCEEDED', 'BREAKER_OPENED', 'HARD_CAP_TRIPPED', 'HARD_CAP_BLOCKED', 'SOFT_CAP_REACHED', 'MONITOR_ONLY_WOULD_BLOCK', 'BREAKER_CLOSED'];
const sent = (b.ledgerAfter && b.ledgerAfter.alertsSent) || {};
const keyOf = (e) => `${U.budgetDay}:${e.type}:${e.scope}:${e.key}`;
const fresh = b.events.filter((e) => ALERT_TYPES.includes(e.type)).filter((e) => A.force || !sent[keyOf(e)]);
const digest = config.trigger === 'schedule' && A.digestOnSchedule;
const alertNeeded = fresh.length > 0 || digest;

const money = (n) => (n === null || n === undefined ? 'no cap' : '$' + (n / 1e9).toFixed(n < 1e7 && n > 0 ? 4 : 2));
const escSlack = (s) => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[*_~`]/g, '');
const escTeams = (s) => String(s === null || s === undefined ? '' : s).replace(/[\[\]()*_~`<>#|]/g, '');
const ICON = { LEDGER_UNTRUSTED: ':no_entry:', LEDGER_RESET: ':recycle:', PROVIDER_BUDGET_EXCEEDED: ':money_with_wings:', BREAKER_OPENED: ':zap:', HARD_CAP_TRIPPED: ':octagonal_sign:', HARD_CAP_BLOCKED: ':octagonal_sign:', SOFT_CAP_REACHED: ':warning:', MONITOR_ONLY_WOULD_BLOCK: ':eyes:', BREAKER_CLOSED: ':white_check_mark:' };
const severity = fresh.some((e) => ['LEDGER_UNTRUSTED', 'PROVIDER_BUDGET_EXCEEDED', 'HARD_CAP_TRIPPED', 'BREAKER_OPENED'].includes(e.type)) ? 'critical' : fresh.length ? 'warning' : 'info';
const tag = config.sandboxMode ? ' [SANDBOX]' : '';
const title = `${severity === 'critical' ? '🚨' : severity === 'warning' ? '⚠️' : '📊'} ${A.title}${digest && !fresh.length ? ': daily digest' : ''}${tag}`;
const c = b.counts;
const resultsSummary = `${c.requests} request(s): ${c.llmCalls - c.providerFailures} LLM (${c.downgrades} downgraded), ${c.fallbacks} fallback, ${c.rejected} rejected`;
const capLine = `Spent today ${money(U.globalSpentNanos)} of ${money(U.globalHardNanos)} (${U.globalPct}%)${U.globalTripped ? ', GLOBAL CAP TRIPPED' : ''}`;
const breakerLine = Object.entries(U.breakers).map(([p, s]) => `${p}: ${s.state}${s.state !== 'CLOSED' ? ` (${s.reason || 'probe'})` : ''}`).join(' · ');
const reasonCounts = {};
for (const r of b.results) if (r.fallback && r.fallback.reason) reasonCounts[r.fallback.reason] = (reasonCounts[r.fallback.reason] || 0) + 1;
const topScopes = U.scopes.filter((s) => s.spentNanos > 0 || s.tripped).slice(0, A.maxRows);
const ccRows = Object.entries(U.costCenters).sort((x, y) => y[1] - x[1]).slice(0, A.maxRows);
const modelRows = Object.entries(U.models).sort((x, y) => y[1] - x[1]).slice(0, A.maxRows);

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: title.slice(0, 150), emoji: true } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: escSlack(`Budget day ${U.budgetDay} · run ${config.runId} · breaker ${b.monitorOnly ? 'MONITOR-ONLY' : 'enforcing'}`) }] },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Daily spend*\n${escSlack(capLine)}` },
    { type: 'mrkdwn', text: `*This run*\n${escSlack(resultsSummary)}, ${escSlack(money(U.runSpendNanos))}` },
    { type: 'mrkdwn', text: `*Provider breakers*\n${escSlack(breakerLine)}` },
    { type: 'mrkdwn', text: `*Fallback reasons*\n${escSlack(Object.entries(reasonCounts).map(([k, v]) => `${k} ×${v}`).join(', ') || 'none')}` },
  ] },
];
if (fresh.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*Events*\n' + fresh.slice(0, 12).map((e) => `${ICON[e.type] || '•'} *${escSlack(e.type)}*: ${escSlack(e.detail)}`).join('\n')).slice(0, 2900) } });
if (topScopes.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*Top spend by scope*\n' + topScopes.map((s) => `• ${escSlack(s.scope)} \`${escSlack(s.key)}\`: ${escSlack(money(s.spentNanos))}${s.hardNanos ? ` of ${escSlack(money(s.hardNanos))} (${s.pctOfCap}%)` : ''}${s.tripped ? ' · TRIPPED' : ''}`).join('\n')).slice(0, 2900) } });
if (ccRows.length || modelRows.length) blocks.push({ type: 'section', fields: [
  { type: 'mrkdwn', text: ('*Cost-center allocation*\n' + (ccRows.map(([k, v]) => `${escSlack(k)}: ${escSlack(money(v))}`).join('\n') || 'none')).slice(0, 1900) },
  { type: 'mrkdwn', text: ('*Spend by model*\n' + (modelRows.map(([k, v]) => `${escSlack(k)}: ${escSlack(money(v))}`).join('\n') || 'none')).slice(0, 1900) },
] });
const warn = [...config.warnings, ...config.configErrors.map((e) => 'CONFIG ERROR: ' + e)];
if (warn.length) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: escSlack(warn.slice(0, 4).join(' · ')).slice(0, 2900) }] });
const slackPayload = { text: `${title}: ${capLine}`.slice(0, 300), blocks: blocks.slice(0, 50), unfurl_links: false, unfurl_media: false };

const T = (text, extra = {}) => ({ type: 'TextBlock', text: escTeams(text), wrap: true, ...extra });
const card = {
  $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', type: 'AdaptiveCard', version: '1.4',
  body: [
    T(title, { size: 'Large', weight: 'Bolder', color: severity === 'critical' ? 'Attention' : severity === 'warning' ? 'Warning' : 'Default' }),
    T(`Budget day ${U.budgetDay} · run ${config.runId} · breaker ${b.monitorOnly ? 'MONITOR-ONLY' : 'enforcing'}`, { isSubtle: true, spacing: 'None' }),
    { type: 'FactSet', facts: [
      { title: 'Daily spend', value: escTeams(capLine) },
      { title: 'This run', value: escTeams(`${resultsSummary}, ${money(U.runSpendNanos)}`) },
      { title: 'Breakers', value: escTeams(breakerLine) },
      { title: 'Fallbacks', value: escTeams(Object.entries(reasonCounts).map(([k, v]) => `${k} x${v}`).join(', ') || 'none') },
    ] },
    ...(fresh.length ? [T('Events', { weight: 'Bolder', spacing: 'Medium' }), ...fresh.slice(0, 12).map((e) => T(`${e.type}: ${e.detail}`, { spacing: 'Small' }))] : []),
    ...(topScopes.length ? [T('Top spend by scope', { weight: 'Bolder', spacing: 'Medium' }), { type: 'FactSet', facts: topScopes.map((s) => ({ title: escTeams(`${s.scope} ${s.key}`), value: escTeams(`${money(s.spentNanos)}${s.hardNanos ? ` of ${money(s.hardNanos)} (${s.pctOfCap}%)` : ''}${s.tripped ? ' TRIPPED' : ''}`) })) }] : []),
    ...(ccRows.length ? [T('Cost-center allocation', { weight: 'Bolder', spacing: 'Medium' }), { type: 'FactSet', facts: ccRows.map(([k, v]) => ({ title: escTeams(k), value: money(v) })) }] : []),
    ...(warn.length ? [T(warn.slice(0, 4).join(' · '), { isSubtle: true, size: 'Small' })] : []),
  ],
};
const teamsPayload = { type: 'message', attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', contentUrl: null, content: card }] };

const textPreview = [title, `Budget day ${U.budgetDay}`, capLine, resultsSummary, `Breakers: ${breakerLine}`, ...fresh.map((e) => `- ${e.type} [${e.scope}:${e.key}] ${e.detail}`)].join('\n');
const blockers = [...A.blockers];
if (!alertNeeded) blockers.push('No new alert events (and not a digest run)');
return [{ json: {
  alertNeeded,
  alertAllowed: blockers.length === 0,
  alertBlockers: blockers,
  channels: A.channels,
  eventKeys: fresh.map(keyOf),
  severity,
  slackPayload,
  teamsPayload,
  textPreview,
  sizes: { slackBlocks: slackPayload.blocks.length, teamsChars: JSON.stringify(teamsPayload).length },
} }];

// ============================================================================
// Dry-Run Alert Preview  (alert not sent: blocked by safety switches or no events)
// ============================================================================
const b = $input.first().json;
return [{ json: { mode: 'not-posted', alertNeeded: b.alertNeeded, alertBlockedBy: b.alertBlockers, channels: b.channels, severity: b.severity, sizes: b.sizes, textPreview: b.textPreview, slackPayload: b.slackPayload, teamsPayload: b.teamsPayload } }];

// ============================================================================
// Build Alert Requests  (one item per configured channel)
// The webhook URL is NOT placed in item data; the HTTP node reads it from $env.
// ============================================================================
const b = $input.first().json;
return b.channels.map((channel) => ({ json: { channel, payload: channel === 'teams' ? b.teamsPayload : b.slackPayload } }));

// ============================================================================
// Alert Result
// Marks each alerted event as sent for this budget day (one alert per event
// per day), only when every channel accepted the message and the ledger is
// persisted (live, non-dry-run).
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const built = $('Cost Alert Builder').first().json;
const commit = $('Commit Spend Ledger').first().json;
const reqs = $('Build Alert Requests').all().map((i) => i.json);
const res = $input.all().map((i) => i.json);
const results = reqs.map((r, i) => {
  const x = res[i] || {};
  const err = x.error ? String(x.error.message || x.error).slice(0, 200) : null;
  const slackError = r.channel === 'slack' && typeof x.data === 'string' && x.data !== 'ok' ? x.data.slice(0, 100) : null;
  return { channel: r.channel, ok: !err && !slackError, error: err || slackError };
});
const allOk = results.every((r) => r.ok);
let recorded = false;
if (allOk && commit.persisted) {
  const sd = $getWorkflowStaticData('global');
  if (sd.llmLedger && sd.llmLedger.day === commit.utilization.budgetDay) {
    sd.llmLedger.alertsSent = sd.llmLedger.alertsSent || {};
    for (const k of built.eventKeys) sd.llmLedger.alertsSent[k] = config.now;
    recorded = true;
  }
}
return [{ json: { mode: 'posted', allOk, results, recorded } }];

// ============================================================================
// Gateway Run Report
// One summary item per execution: mode, routing counts, fallback reasons,
// spend, breaker states, alert outcome, persistence. No prompts, no secrets.
// ============================================================================
const { config, safetyDecisions } = $('Config & Safety Gate').first().json;
const g = $('Gateway Response').first().json;
const alert = $('Cost Alert Builder').first().json;
const last = $input.first().json;
const reasons = {};
for (const r of g.results) if (r.fallback && r.fallback.reason) reasons[r.fallback.reason] = (reasons[r.fallback.reason] || 0) + 1;
let alertStatus;
if (last.mode === 'posted') alertStatus = last.allOk ? 'POSTED' : 'POST_FAILED';
else if (!alert.alertNeeded) alertStatus = 'NO_ALERT_NEEDED';
else alertStatus = 'BLOCKED';
return [{ json: {
  runId: config.runId,
  mode: config.sandboxMode ? 'SANDBOX' : config.dryRun ? 'DRY_RUN' : 'LIVE',
  breakerMode: g.monitorOnly ? 'MONITOR_ONLY' : 'ENFORCING',
  trigger: config.trigger,
  source: g.source,
  budgetDay: g.utilization.budgetDay,
  requests: { total: g.counts.requests, llmOk: g.results.filter((r) => r.status === 'LLM_OK' || r.status === 'LLM_DOWNGRADED').length, downgraded: g.counts.downgrades, fallback: g.counts.fallbacks, rejected: g.counts.rejected, providerFailures: g.counts.providerFailures },
  statuses: Object.fromEntries(g.results.map((r) => [r.request_id, r.status])),
  fallbackReasons: reasons,
  spend: g.response.spend,
  breakers: g.utilization.breakers,
  trips: g.utilization.trips,
  events: g.events.map((e) => e.type + ':' + e.scope + ':' + e.key),
  alert: { status: alertStatus, severity: alert.severity, blockers: alert.alertBlockers, results: last.results || null },
  ledger: { source: g.ledgerSource, trusted: g.ledgerTrusted, errors: g.ledgerErrors, rolledOver: g.rolledOver, persisted: g.persisted, note: g.persistNote },
  warnings: config.warnings,
  configErrors: config.configErrors,
  safetyDecisions,
} }];
